import { Directive, Input } from '@angular/core';
import { Router } from '@angular/router';
import { AccountService } from '@honoregaming/account';
import { DestroySubject, mul, TaxesService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ContentComponent } from '@honoregaming/templating';
import { TaxType } from '@honoregaming/types';
import { MessageService } from '@honoregaming/ui';
import { Provider } from 'projects/customer/hg-account/src/lib/models/provider.model';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';

@Directive()
export abstract class ProviderBaseComponent extends DestroySubject {
  @Input() provider!: Provider;

  TaxType = TaxType;

  protected constructor(
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    protected readonly i18nService: I18nService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    protected readonly accountService: AccountService
  ) {
    super();
  }

  openTaxInformations(taxType: TaxType, baseAmount: number): void {
    const placeholderValues: string[] =
      taxType === TaxType.Deposit
        ? this.buildTaxPlaceholderValues(this.taxesService.getDepositTaxConfiguration()?.rate, baseAmount)
        : this.buildTaxPlaceholderValues(this.taxesService.getWithdrawalTaxConfiguration()?.rate, baseAmount);

    this.messageService.sendComponentMessage(
      ContentComponent,
      {
        name: `${taxType.toLowerCase()}-tax-infos`,
        placeholderValues
      },
      {
        maxWidth: 500,
        canBeDismissed: true,
        displayClose: true
      }
    );
  }

  validateIdentity(): void {
    this.accountService.editProfileInformationClicked();
    this.router.navigate(['/myaccount/informations']);
    this.transactionPopupService.close();
  }

  private buildTaxPlaceholderValues(rate: number | undefined, baseAmount: number): string[] {
    const ratePercentage: string = mul(rate ?? 0, 100).toString();
    const amountLabel: string =
      baseAmount > 0 ? baseAmount.toString() : this.i18nService.translateSync('ACCOUNT.TRANSACTION.TRANSACTION_AMOUNT');

    return [ratePercentage, amountLabel];
  }
}
