import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { OperationType } from 'projects/customer/hg-account/src/lib/models/operation.model';

@Component({
  selector: 'hg-deposit-withdrawal-amount-selector',
  templateUrl: './deposit-withdrawal-amount-selector.component.html',
  styleUrls: ['./deposit-withdrawal-amount-selector.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositWithdrawalAmountSelectorComponent {
  @Input() amounts: number[];
  @Input() currentBalance?: number;
  @Input() maximumAmount: number;
  @Input() type!: OperationType.Deposit | OperationType.Withdrawal;

  @Output() amountSelected = new EventEmitter<number>();

  onAmountSelected(amount: number) {
    if (this.currentBalance) {
      if (amount < this.currentBalance) {
        this.amountSelected.emit(amount);
      } else {
        this.amountSelected.emit(this.currentBalance);
      }
    } else {
      this.amountSelected.emit(amount);
    }
  }
}
